/*The BankCrad is a card that can deposit or withdraw money.*/
class BankCard {
  /*The unique identifier of the bank card*/
  CardID: number;
  /*The status of the bank card*/
  CardStatus: CardStatus;
  /*The catalog of the bank card*/
  Catalog: CardCatalog;
  /*The password of the bank card*/
  Password: number;
  /*The balance of the bank card*/
  Balance: number;
  /*The user who owns the bank card*/
  BelongedUser: User;
}
/*Bank user information.*/
class User {
  /*The id of the user*/
  UserID: number;
  /*The name of the user*/
  Name: string;
  /*The address of the user*/
  Address: string;
  /*The bank card owned by the user*/
  OwnedCard: BankCard;
}
enum CardStatus {
  NORMAL = "NORMAL",
  SUSPEND = "SUSPEND",
  CANNEL = "CANNEL",
}
enum CardCatalog {
  CREDIT = "CREDIT",
  DESPOSIT = "DESPOSIT",
}
const map = new Map();
map.set(BankCard, []);
map.set(User, []);
const getRepository = <T,>(clazz: new (...args: any[]) => T) => {
  return map.get(clazz) as T[];
};
export { CardStatus, CardCatalog, BankCard, User, getRepository };

typescript.originalService:
class AutomatedTellerMachineSystem_AutoGenerated {
  /*SystemVariable Start*/
  PasswordValidated: boolean;
  WithdrawedNumber: number;
  InputCard: BankCard;
  CardIDValidated: boolean;
  IsDeposit: boolean;
  IsWithdraw: boolean;
  DepositedNumber: number;
  /*SystemVariable End*/

  /*if the card password and id is validated, and the input card exist, show the input card balance*/
  checkBalance(): number {
    /*Definition Start*/
    let inputCard: BankCard = l({
      logic: () =>
        getRepository(BankCard).find(
          (o: any) =>
            l({
              logic: () => o.Password === this.InputCard.Password,
              description: "o.Password=InputCard.Password",
            })
              .and({
                logic: () => o.CardID === this.InputCard.CardID,
                description: "o.CardID=InputCard.CardID",
              })
              .build().pass,
        ),
      description:
        "BankCard.allInstance()->any(o|o.Password=InputCard.Passwordando.CardID=InputCard.CardID)",
    }).build().pass;
    let isValid: boolean = l({
      logic: () => StandardOPs.oclIsUndefined(this.InputCard) === false,
      description: "InputCard.oclIsUndefined()=false",
    }).build().pass;
    let isValidPassword: boolean = l({
      logic: () => this.PasswordValidated,
      description: "PasswordValidated",
    }).build().pass;
    let isValidCardID: boolean = l({
      logic: () => this.CardIDValidated,
      description: "CardIDValidated",
    }).build().pass;
    let ob: BankCard = l({
      logic: () => inputCard,
      description: "inputCard",
    }).build().pass;
    let balanceValid: boolean = l({
      logic: () => ob.Balance >= 0,
      description: "ob.Balance>=0",
    }).build().pass;
    let isValid: boolean = l({
      logic: () => isValidPassword,
      description: "isValidPassword",
    })
      .and({
        logic: () => isValidCardID,
        description: "isValidCardID",
      })
      .build().pass;
    /*Definition End*/

    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
      l({
        logic: () => isValid === true,
        description: "isValid=true",
      }).build();
    if (!isPreconditionPass) {
      throw new PreconditionError(preconditionErrorMessage);
    }
    /*Precondition End*/

    /*Postcondition Start*/
    return l({
      execute: () => ob.Balance,
      description: "result=ob.Balance",
    })
      .and({
        execute: () => getRepository(BankCard).push(ob),
        description: "BankCard.allInstance()->includes(ob)",
      })
      .and({
        execute: () => (balanceValid = true),
        description: "balanceValid=true",
      })
      .build().value;
    /*Postcondition End*/
  }
}
export { AutomatedTellerMachineSystem_AutoGenerated };

